package os.aios.codex;
import android.content.Context;import android.system.Os;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Phone-owned npm installations. A version becomes visible only after successful completion. */
final class CliPackages implements RuntimeExtension {
 private final Context context;private final File root;private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final android.content.SharedPreferences prefs;private final Map<String,Process> running=new ConcurrentHashMap<>();
 CliPackages(Context c)throws Exception{context=c;root=new File(c.getFilesDir(),"cli");root.mkdirs();prefs=c.getSharedPreferences("cli_packages",0);prepare(c);publish();for(Map.Entry<String,?> e:prefs.getAll().entrySet())if(e.getKey().startsWith("job:")){JSONObject job=new JSONObject(String.valueOf(e.getValue()));if(Set.of("queued","running").contains(job.optString("state"))){job.put("state","interrupted");save(e.getKey(),job);}}}
 static String node(Context c){return os.aios.host.HostBindings.nativePayload(c,"libaios_node.so").getAbsolutePath();}
 static synchronized void prepare(Context c)throws Exception{
  File root=new File(c.getFilesDir(),"cli"),bin=new File(root,"bin");bin.mkdirs();
  for(String name:new String[]{"node","npm","npx"}){
   File link=new File(bin,name);String target=os.aios.host.HostBindings.nativePayload(c,name.equals("node")?"libaios_node.so":"libaios_cli_launcher.so").getAbsolutePath();
   try{if(!Os.readlink(link.getAbsolutePath()).equals(target))link.delete();}catch(Exception missing){link.delete();}
   if(!Files.exists(link.toPath(),LinkOption.NOFOLLOW_LINKS))Os.symlink(target,link.getAbsolutePath());
  }
  File marker=new File(root,".runtime-22.23.4-v2");if(!marker.exists()){
   try(InputStream in=c.getAssets().open("cli-runtime/dispatch.cjs")){Files.copy(in,new File(root,"dispatch.cjs").toPath(),StandardCopyOption.REPLACE_EXISTING);}
   try(java.util.zip.ZipInputStream zip=new java.util.zip.ZipInputStream(c.getAssets().open("cli-runtime/npm.zip"))){java.util.zip.ZipEntry entry;while((entry=zip.getNextEntry())!=null){File out=new File(root,entry.getName()).getCanonicalFile();if(!out.toPath().startsWith(root.getCanonicalFile().toPath()))throw new IOException(c.getString(R.string.extension_error_invalid_entry));if(entry.isDirectory())out.mkdirs();else{out.getParentFile().mkdirs();Files.copy(zip,out.toPath(),StandardCopyOption.REPLACE_EXISTING);}}}
   os.aios.core.CompatFiles.writeString(marker.toPath(),"22.23.4");
  }
 }
 private static void extract(Context c,String asset,File dest)throws Exception{String[] children=c.getAssets().list(asset);if(children!=null&&children.length>0){dest.mkdirs();for(String child:children)extract(c,asset+"/"+child,new File(dest,child));}else{dest.getParentFile().mkdirs();try(InputStream in=c.getAssets().open(asset)){byte[] bytes=in.readAllBytes();if(!dest.isFile()||!Arrays.equals(bytes,Files.readAllBytes(dest.toPath())))Files.write(dest.toPath(),bytes);}}}
 static void environment(Context c,Map<String,String> env){File root=new File(c.getFilesDir(),"cli");File fallbackHome=new File(root,"home");fallbackHome.mkdirs();String inheritedHome=env.get("HOME");if(inheritedHome==null||inheritedHome.isBlank()||!new File(inheritedHome).canWrite())env.put("HOME",fallbackHome.getAbsolutePath());env.put("PATH",new File(root,"bin")+":"+os.aios.host.HostBindings.systemCommandPath());env.put("AIOS_NODE",node(c));env.put("AIOS_CLI_ROOT",root.getAbsolutePath());env.put("npm_config_cache",new File(root,"cache").getAbsolutePath());env.put("npm_config_script_shell",os.aios.host.HostBindings.commandShell());env.put("TMPDIR",c.getCacheDir().getAbsolutePath());File ca=new File(c.getFilesDir(),"android-ca.pem");if(ca.isFile())env.put("NODE_EXTRA_CA_CERTS",ca.getAbsolutePath());}
 private synchronized void save(String key,JSONObject object)throws Exception{if(!prefs.edit().putString(key,object.toString()).commit())throw new IOException(context.getString(R.string.extension_error_save_failed));}
 private String id(JSONObject p)throws Exception{String id=p.getString("id");if(!id.matches("[a-zA-Z0-9_-]{1,80}"))throw new IllegalArgumentException(context.getString(R.string.extension_error_invalid_id));return id;}
 public synchronized JSONObject call(String action,JSONObject p)throws Exception{
  if(action.equals("reconcile")){JSONObject installed=p.getJSONObject("packages");prefs.edit().putString("inventory",installed.toString()).commit();for(Map.Entry<String,?> e:new HashMap<>(prefs.getAll()).entrySet())if(e.getKey().startsWith("pkg:")){JSONObject item=new JSONObject(String.valueOf(e.getValue()));String owner=item.optString("owner_package");if(owner.isEmpty())continue;if(!installed.has(owner)){call("cancel",new JSONObject().put("id",item.getString("id")));prefs.edit().remove(e.getKey()).commit();publish();if(item.has("directory"))delete(new File(item.getString("directory")));}else{long version=installed.getLong(owner);if(item.has("owner_version")&&item.getLong("owner_version")!=version)item.put("state","needs_revalidation");item.put("owner_version",version);save(e.getKey(),item);}}return new JSONObject().put("state","succeeded");}
  if(action.equals("status"))return new JSONObject(prefs.getString("job:"+id(p),"{}"));
  if(action.equals("list")){JSONArray items=new JSONArray();for(Map.Entry<String,?> e:prefs.getAll().entrySet())if(e.getKey().startsWith("pkg:"))items.put(new JSONObject(String.valueOf(e.getValue())));return new JSONObject().put("state","succeeded").put("items",items).put("node",node(context)).put("node_available",new File(node(context)).canExecute()).put("platform","android-arm64");}
  String id=id(p);
  if(action.equals("cancel")){JSONObject job=new JSONObject(prefs.getString("job:"+id,"{}"));job.put("cancel_requested",true);save("job:"+id,job);Process child=running.get(id);if(child!=null)child.destroy();return job;}
  if(action.equals("remove")){JSONObject pending=new JSONObject(prefs.getString("job:"+id,"{}"));if(Set.of("queued","running").contains(pending.optString("state"))||running.containsKey(id))throw new IllegalStateException(context.getString(R.string.extension_error_cancel_first));JSONObject old=new JSONObject(prefs.getString("pkg:"+id,"{}"));prefs.edit().remove("pkg:"+id).commit();publish();if(old.has("directory"))delete(new File(old.getString("directory")));return new JSONObject().put("state","succeeded").put("id",id);}
  if(action.equals("register")){
   String name=p.getString("command"),runtime=p.optString("runtime","node");if(!name.matches("[A-Za-z0-9_-]{1,80}")||Set.of("node","npm","npx").contains(name)||!Set.of("node","shell","executable").contains(runtime))throw new IllegalArgumentException(context.getString(R.string.extension_error_invalid_runtime));
   File file=new File(p.getString("path")).getCanonicalFile();if(!file.isAbsolute()||!file.isFile()||!file.canRead()||runtime.equals("executable")&&!file.canExecute())throw new IOException(context.getString(R.string.extension_error_command_missing));
   JSONObject commands=new JSONObject().put(name,new JSONObject().put("path",file.getAbsolutePath()).put("runtime",runtime));checkConflicts(id,commands);
   JSONObject previous=new JSONObject(prefs.getString("pkg:"+id,"{}"));JSONObject item=new JSONObject().put("id",id).put("kind","registration").put("commands",commands).put("owner_package",p.has("owner_package")?p.getString("owner_package"):previous.optString("owner_package")).put("state","registered_unverified").put("updated_at",System.currentTimeMillis());JSONObject inventory=new JSONObject(prefs.getString("inventory","{}"));String owner=item.optString("owner_package");if(!owner.isEmpty()&&inventory.has(owner))item.put("owner_version",inventory.getLong(owner));replace(id,item,previous);return item;
  }
  if(!action.equals("install"))throw new IllegalArgumentException(context.getString(R.string.extension_error_unknown_action));
  String spec=p.getString("package");if(!spec.matches("(?:@[a-z0-9._-]+/)?[a-z0-9._-]+@[a-zA-Z0-9.*+~^_-]+(?:\\.[a-zA-Z0-9.*+~^_-]+)*"))throw new IllegalArgumentException(context.getString(R.string.extension_error_package_version));
  if(root.getUsableSpace()<256L*1024*1024)throw new IOException(context.getString(R.string.extension_error_space));
  if(!new File(node(context)).canExecute())throw new IllegalStateException(context.getString(R.string.extension_error_node_missing));
  JSONObject prior=new JSONObject(prefs.getString("job:"+id,"{}"));if(Set.of("running","queued").contains(prior.optString("state")))return prior;
  JSONObject job=new JSONObject().put("id",id).put("package",spec).put("state","queued").put("owner_package",p.has("owner_package")?p.getString("owner_package"):new JSONObject(prefs.getString("pkg:"+id,"{}")).optString("owner_package")).put("started_at",System.currentTimeMillis());save("job:"+id,job);
  boolean scripts=p.optBoolean("run_scripts",false);worker.execute(()->install(id,spec,scripts));return job;
 }
 private void install(String id,String spec,boolean scripts){File stage=new File(root,"packages/"+id+"/"+UUID.randomUUID());try{
  stage.mkdirs();JSONObject job=new JSONObject(prefs.getString("job:"+id,"{}"));if(job.optBoolean("cancel_requested"))throw new InterruptedException();job.put("state","running");save("job:"+id,job);
  File log=new File(stage,"install.log");ProcessBuilder builder=new ProcessBuilder(node(context),new File(root,"npm/bin/npm-cli.js").getAbsolutePath(),"install","--prefix",stage.getAbsolutePath(),"--no-audit","--no-fund","--save-exact",scripts?"--ignore-scripts=false":"--ignore-scripts","--",spec).directory(stage).redirectErrorStream(true).redirectOutput(log);
  environment(context,builder.environment());builder.environment().put("HOME",new File(root,"home").getAbsolutePath());new File(root,"home").mkdirs();AndroidNetwork.applyProxy(builder.environment(),AndroidNetwork.proxyUrl(context));
  Process child=builder.start();running.put(id,child);long deadline=System.currentTimeMillis()+TimeUnit.MINUTES.toMillis(15);while(!child.waitFor(1,TimeUnit.SECONDS)){if(new JSONObject(prefs.getString("job:"+id,"{}")).optBoolean("cancel_requested")){child.destroyForcibly();throw new InterruptedException();}if(log.length()>8*1024*1024L||System.currentTimeMillis()>deadline){child.destroyForcibly();throw new IOException(context.getString(R.string.extension_error_budget));}}if(child.exitValue()!=0)throw new IOException("npm_exit_"+child.exitValue());
  job=new JSONObject(prefs.getString("job:"+id,"{}"));if(job.optBoolean("cancel_requested"))throw new InterruptedException();
  String name=spec.substring(0,spec.lastIndexOf('@'));File module=new File(stage,"node_modules/"+name);JSONObject manifest=new JSONObject(os.aios.core.CompatFiles.readString(new File(module,"package.json").toPath()));Object raw=manifest.opt("bin");JSONObject bins=raw instanceof JSONObject?(JSONObject)raw:new JSONObject();if(raw instanceof String)bins.put(name.substring(name.lastIndexOf('/')+1),raw);
  JSONObject commands=new JSONObject();for(Iterator<String> it=bins.keys();it.hasNext();){String command=it.next();if(!command.matches("[A-Za-z0-9_-]{1,80}")||Set.of("node","npm","npx").contains(command))throw new IOException(context.getString(R.string.extension_error_reserved));File file=new File(module,bins.getString(command)).getCanonicalFile();if(!file.toPath().startsWith(module.getCanonicalFile().toPath())||!file.isFile())throw new IOException(context.getString(R.string.extension_error_invalid_binary));commands.put(command,file.getAbsolutePath());}
  String owner=job.optString("owner_package");if(!owner.isEmpty()&&prefs.contains("inventory")&&!new JSONObject(prefs.getString("inventory","{}")).has(owner))throw new IOException(context.getString(R.string.extension_error_owner_removed));
  if(commands.length()==0)throw new IOException(context.getString(R.string.extension_error_no_commands));
  synchronized(this){if(!owner.isEmpty()&&prefs.contains("inventory")&&!new JSONObject(prefs.getString("inventory","{}")).has(owner))throw new IOException(context.getString(R.string.extension_error_owner_removed));checkConflicts(id,commands);
   JSONObject previous=new JSONObject(prefs.getString("pkg:"+id,"{}"));
   JSONObject installed=new JSONObject().put("id",id).put("package",name).put("version",manifest.getString("version")).put("owner_package",job.optString("owner_package")).put("directory",stage.getAbsolutePath()).put("commands",commands).put("state","installed_unverified").put("updated_at",System.currentTimeMillis());JSONObject inventory=new JSONObject(prefs.getString("inventory","{}"));if(!owner.isEmpty()&&inventory.has(owner))installed.put("owner_version",inventory.getLong(owner));replace(id,installed,previous);if(previous.has("directory")){try{delete(new File(previous.getString("directory")));}catch(Exception cleanup){android.util.Log.w("AIOSCli","Old version cleanup",cleanup);}}}
  job.put("state","succeeded").put("commands",commands).put("verified_execution",false);save("job:"+id,job);
 }catch(Exception e){try{JSONObject job=new JSONObject(prefs.getString("job:"+id,"{}"));job.put("state",e instanceof InterruptedException?"cancelled":"failed").put("reason",e.getMessage()).put("log_path",new File(stage,"install.log").getAbsolutePath());save("job:"+id,job);}catch(Exception ignored){}}finally{running.remove(id);try{trimCache();}catch(Exception cleanup){android.util.Log.w("AIOSCli","Cache cleanup",cleanup);}}}
 private void replace(String id,JSONObject item,JSONObject previous)throws Exception{save("pkg:"+id,item);try{publish();}catch(Exception failed){if(previous.length()==0)prefs.edit().remove("pkg:"+id).commit();else save("pkg:"+id,previous);try{publish();}catch(Exception restore){failed.addSuppressed(restore);}throw failed;}}
 private void trimCache()throws Exception{Path cache=new File(root,"cache").toPath();if(!Files.isDirectory(cache,LinkOption.NOFOLLOW_LINKS))return;try(java.util.stream.Stream<Path> walk=Files.walk(cache)){List<Path> files=walk.filter(p->Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)).sorted(Comparator.comparingLong(p->p.toFile().lastModified())).collect(java.util.stream.Collectors.toList());long total=0;for(Path p:files)total+=Files.size(p);for(Path p:files){if(total<=256L*1024*1024)break;long bytes=Files.size(p);Files.deleteIfExists(p);total-=bytes;}}}
 private void checkConflicts(String id,JSONObject commands)throws Exception{for(Map.Entry<String,?> e:prefs.getAll().entrySet())if(e.getKey().startsWith("pkg:")&&!e.getKey().equals("pkg:"+id)){JSONObject existing=new JSONObject(String.valueOf(e.getValue())).getJSONObject("commands");for(Iterator<String> it=commands.keys();it.hasNext();)if(existing.has(it.next()))throw new IOException(context.getString(R.string.extension_error_command_conflict));}}
 private synchronized void publish()throws Exception{
  JSONObject commands=new JSONObject();for(Map.Entry<String,?> e:prefs.getAll().entrySet())if(e.getKey().startsWith("pkg:")){JSONObject bins=new JSONObject(String.valueOf(e.getValue())).getJSONObject("commands");for(Iterator<String> it=bins.keys();it.hasNext();){String name=it.next();commands.put(name,bins.get(name));}}
  File file=new File(root,"commands.json"),temp=new File(root,"commands.json.tmp");os.aios.core.CompatFiles.writeString(temp.toPath(),commands.toString());Files.move(temp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);
  File bin=new File(root,"bin");for(File entry:Objects.requireNonNull(bin.listFiles()))if(!Set.of("node","npm","npx").contains(entry.getName())&&!commands.has(entry.getName()))entry.delete();
  for(Iterator<String> it=commands.keys();it.hasNext();){File link=new File(bin,it.next());String target=os.aios.host.HostBindings.nativePayload(context,"libaios_cli_launcher.so").getAbsolutePath();try{if(!Os.readlink(link.getAbsolutePath()).equals(target))link.delete();}catch(Exception ignored){link.delete();}if(!Files.exists(link.toPath(),LinkOption.NOFOLLOW_LINKS))Os.symlink(target,link.getAbsolutePath());}
 }
 private void delete(File target)throws Exception{Path base=new File(root,"packages").getCanonicalFile().toPath(),path=target.getCanonicalFile().toPath();if(!path.startsWith(base)||path.equals(base))throw new SecurityException(context.getString(R.string.extension_error_delete_scope));try(java.util.stream.Stream<Path> walk=Files.walk(path)){for(Path entry:walk.sorted(Comparator.reverseOrder()).collect(java.util.stream.Collectors.toList()))Files.delete(entry);}}
}
